```javascript
function switchAdjectiveOrder(sentence) {
  // Define regex pattern for identifying adjectives and their position in the sentence
  const regexPattern = /(([A-Z][a-z]+(?:[\s-][a-z]+)*\.?)(\s+)[A-Z][a-z]+(?:[\s-][a-z]+)*){2}/g;

  let match;
  let newSentence = "";

  // Find all pairs of adjacent adjectives in the sentence
  while ((match = regexPattern.exec(sentence)) !== null) {
    const adjPair = match[0].trim();
    const [firstAdj, secondAdj] = adjPair.split(/ [\\s-]+/);

    // Swap the order of the adjectives and add them back to the new sentence
    newSentence += ` ${secondAdj} ${firstAdj}`;
  }

  // Add the remaining words in the original order to the new sentence
  newSentence += sentence.substring(regexPattern.lastIndex);

  return newSentence.trim();
}

// Test cases
console.log(switchAdjectiveOrder("Beautiful green trees are in the park")); // "Green beautiful trees are in the park"
console.log(switchAdjectiveOrder("Large red apples are delicious")); // "Red large apples are delicious"
console.log(switchAdjectiveOrder("The quick brown fox jumps over the lazy dog")); // "The lazy brown fox jumps over the quick dog"
```

This function uses a regular expression pattern to find pairs of adjacent adjectives in the input sentence. It then swaps their order and adds them back to the new sentence. The remaining words are added to the new sentence in their original order.

