function sortJsonKeys(jsonObject, weights) {
  // Check if weights are provided as an object with key-value pairs representing the weights for each key
  if (typeof weights !== "object" || Array.isArray(weights)) {
    throw new Error("Weights must be an object with key-value pairs.");
  }

  // Create an array of key-value pairs from the JSON object and sort it based on the given weights
  const sortedArray = Object.entries(jsonObject).sort((a, b) => {
    const weightA = weights[a[0]] || 0;
    const weightB = weights[b[0]] || 0;

    return weightB - weightA; // Sort in descending order based on weights
  });

  // Extract the sorted keys and values and return them as a new JSON object
  const result = {};
  for (const [key, value] of sortedArray) {
    result[key] = value;
  }

  return result;
}
```

To use this function, you can pass the JSON object and an optional object containing the weights for each key:

```javascript
const jsonObject = {
  b: 2,
  a: 3,
  c: 1
};

const weights = {
  a: 50,
  b: 30,
  c: 20
};

const sortedJsonObject = sortJsonKeys(jsonObject, weights);
console.log(sortedJsonObject); // { a: 3, b: 2 }
```

